def downgrade():
    # Dropping standalone indexes first can break MySQL foreign-key supporting indexes.
    # Reverse dependency order; MySQL removes each table's indexes and triggers with it.
    for name in (
        "ac_trace_events",
        "ac_defects",
        "ac_assertion_results",
        "ac_test_executions",
        "ac_artifacts",
        "sb_booking_slots",
        "ac_test_runs",
        "sb_bookings",
        "ac_target_versions",
        "sb_booking_drafts",
        "ac_test_cases",
        "ac_targets",
        "sb_rooms",
        "ac_users",
        "ac_knowledge_documents",
        "ac_fault_profiles",
    ):
        op.drop_table(name)


def _guard(name, table, action, body):
    op.execute(
        sa.text(
            f"CREATE TRIGGER `{name}` BEFORE {action} ON `{table}` FOR EACH ROW BEGIN {body} END"
        )
    )


def _reject(code):
    return f"SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '{code}';"


def _freeze_columns(columns):
    comparison = " OR ".join(f"NOT (OLD.`{col}` <=> NEW.`{col}`)" for col in columns)
    return f"IF {comparison} THEN {_reject('frozen_execution_config')} END IF;"


def _create_guards():
    for table in (
        "ac_target_versions",
        "ac_knowledge_documents",
        "ac_fault_profiles",
        "ac_trace_events",
        "ac_assertion_results",
        "ac_artifacts",
    ):
        for action in ("UPDATE", "DELETE"):
            _guard(
                f"guard_{table}_{action.lower()}",
                table,
                action,
                _reject("immutable_revision_or_evidence"),
            )

    approval = (
        "IF NEW.review_status = 'approved' AND NOT EXISTS "
        "(SELECT 1 FROM ac_users WHERE id=NEW.reviewer_id AND role='reviewer' AND enabled=1) "
        f"THEN {_reject('reviewer_required')} END IF;"
        "IF NEW.review_status = 'approved' AND EXISTS "
        "(SELECT 1 FROM ac_test_cases WHERE family_key=NEW.family_key AND review_status='approved' "
        "AND dataset_split<>NEW.dataset_split) "
        f"THEN {_reject('approved_family_split_conflict')} END IF;"
    )
    _guard("guard_case_insert", "ac_test_cases", "INSERT", approval)
    _guard(
        "guard_case_update",
        "ac_test_cases",
        "UPDATE",
        f"IF OLD.review_status='approved' THEN {_reject('approved_case_immutable')} END IF;"
        + approval,
    )
    _guard(
        "guard_case_delete",
        "ac_test_cases",
        "DELETE",
        f"IF OLD.review_status='approved' THEN {_reject('approved_case_immutable')} END IF;",
    )

    _guard(
        "guard_run_config",
        "ac_test_runs",
        "UPDATE",
        _freeze_columns(
            (
                "run_uuid",
                "target_version_id",
                "created_by",
                "manifest_json",
                "manifest_hash",
                "budget_json",
            )
        ),
    )
    _guard("guard_run_delete", "ac_test_runs", "DELETE", _reject("execution_evidence_retained"))
    _guard(
        "guard_execution_config",
        "ac_test_executions",
        "UPDATE",
        _freeze_columns(
            (
                "execution_uuid",
                "run_id",
                "case_revision_id",
                "repeat_no",
                "seed",
                "scope_id",
                "session_id",
                "input_snapshot_json",
            )
        )
        + f"IF NEW.attempt_no < OLD.attempt_no THEN {_reject('attempt_cannot_decrease')} END IF;",
    )
    _guard(
        "guard_execution_delete",
        "ac_test_executions",
        "DELETE",
        _reject("execution_evidence_retained"),
    )
    _guard(
        "guard_execution_insert",
        "ac_test_executions",
        "INSERT",
        "IF NOT EXISTS (SELECT 1 FROM ac_test_cases WHERE id=NEW.case_revision_id "
        f"AND review_status='approved') THEN {_reject('approved_case_required')} END IF;",
    )

    defect_scope = (
        "IF NOT EXISTS (SELECT 1 FROM ac_test_executions e JOIN ac_test_runs r ON r.id=e.run_id "
        "JOIN ac_target_versions v ON v.id=r.target_version_id "
        "WHERE e.id=NEW.first_execution_id AND v.target_id=NEW.target_id) "
        f"THEN {_reject('defect_target_mismatch')} END IF;"
    )
    for action in ("INSERT", "UPDATE"):
        _guard(f"guard_defect_{action.lower()}", "ac_defects", action, defect_scope)
